def _target(endpoint: str) -> tuple[str, bool]:
    value = str(endpoint).strip()
    if not value:
        raise ValueError("endpoint must not be empty")
    parsed = urlsplit(value if "://" in value else f"https://{value}")
    if parsed.scheme in ("https", "grpcs"):
        secure = True
    elif parsed.scheme in ("http", "grpc"):
        secure = False
    else:
        raise ValueError(f"unsupported endpoint scheme: {parsed.scheme}")
    target = parsed.netloc or parsed.path
    if not target or parsed.path not in ("", "/") and parsed.netloc:
        raise ValueError("endpoint must contain only an authority")
    return target, secure


def _validate(credentials: Credentials, secure: bool) -> None:
    token = credentials.bearer_token
    if token is not None and (not token.strip() or "\n" in token or "\r" in token):
        raise ValueError("invalid bearer credential")
    if token and not secure:
        raise ValueError("bearer credentials require a secure endpoint")
    if (credentials.certificate_chain is None) != (credentials.private_key is None):
        raise ValueError("certificate_chain and private_key must be supplied together")


